"""Standalone offline HTML slide renderer. Run: python render.py [presentation.json]."""
from pathlib import Path
import html
import io
import json
import keyword
import sys
import token
import tokenize

ROOT = Path(__file__).resolve().parent
def esc(value):
    return html.escape(str(value), quote=True)

def highlight(code):
    """Preserve exact source spacing while adding token classes; no dependencies."""
    lines = code.splitlines(keepends=True)
    offsets = [0]
    for line in lines:
        offsets.append(offsets[-1] + len(line))
    def position(pos):
        row, col = pos
        return offsets[min(row - 1, len(offsets) - 1)] + col
    result, cursor = [], 0
    for t in tokenize.generate_tokens(io.StringIO(code).readline):
        if t.type in (token.ENDMARKER, token.ENCODING, token.INDENT, token.DEDENT):
            continue
        start, end = position(t.start), position(t.end)
        result.append(esc(code[cursor:start]))
        cls = 'kw' if t.string in keyword.kwlist else {token.STRING:'str', token.NUMBER:'num', tokenize.COMMENT:'comment'}.get(t.type, '')
        result.append(f'<span class="{cls}">{esc(code[start:end])}</span>' if cls else esc(code[start:end]))
        cursor = end
    result.append(esc(code[cursor:]))
    return ''.join(result)

PATTERNS = {'?':'0111010001001100000000100','×':'1000101010001000101010001','✓':'0000000001000101010001000'}
def led(symbol):
    cells=''.join(f'<rect x="{14+(i%5)*29}" y="{14+(i//5)*29}" width="18" height="18" rx="2" fill="{("#64ddbf" if cell=="1" else "#36445c")}"/>' for i,cell in enumerate(PATTERNS[symbol]))
    return f'<svg class="led" viewBox="0 0 162 162" role="img" aria-label="Світлодіодна матриця 5 на 5: {esc(symbol)}"><rect width="162" height="162" rx="14" fill="#17263e"/>{cells}</svg>'

def flow():
    return '''<svg class="flowchart" viewBox="0 0 1080 390" role="img" aria-label="Початок після струшування. Очистити екран, обрати number від 1 до 3. Якщо number дорівнює 3, показати галочку; інакше перевірити 2 та показати хрестик; інакше показати знак питання. Кінець.">
<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="#263b55"/></marker></defs>
<g fill="none" stroke="#263b55" stroke-width="3" marker-end="url(#arrow)"><path d="M170 83H205"/><path d="M405 83H435"/><path d="M635 83H705"/><path d="M535 146V255"/><path d="M795 146V255"/><path d="M885 83H960V255"/><path d="M535 315V355H795"/><path d="M960 315V355H795"/><path d="M795 315V335"/></g>
<g stroke="#263b55" stroke-width="3" fill="#e5f8f2"><rect x="10" y="51" width="160" height="64" rx="32"/><rect x="205" y="38" width="200" height="90"/><path d="M535 20L635 83L535 146L435 83Z"/><path d="M795 20L885 83L795 146L705 83Z"/><path d="M475 255H615L595 315H455Z"/><path d="M735 255H875L855 315H715Z"/><path d="M915 255H1045L1025 315H895Z"/><rect x="725" y="335" width="140" height="42" rx="21"/></g>
<g text-anchor="middle" fill="#17263e" font-family="Segoe UI,Arial,sans-serif" font-size="23" font-weight="650"><text x="90" y="78">Після</text><text x="90" y="103">струшування</text><text x="305" y="67">Очистити екран</text><text x="305" y="101">number ← 1…3</text><text x="535" y="91">number = 3?</text><text x="795" y="91">number = 2?</text><text x="535" y="294">Показати ✓</text><text x="795" y="294">Показати ×</text><text x="970" y="294">Показати ?</text><text x="795" y="364">Кінець</text><text x="662" y="66">ні</text><text x="920" y="65">ні</text><text x="564" y="211">так</text><text x="824" y="211">так</text></g></svg>'''

def body(s):
    kind=s['layout']
    sub=f'<p class="subtitle">{esc(s.get("subtitle", ""))}</p>'
    if kind=='hero':
        return f'<div class="hero-copy"><p class="lesson-label">{esc(s["label"])}</p><h1>{esc(s["title"])}</h1>{sub}</div><div class="orb" aria-hidden="true"><span>?</span><i></i></div>'
    heading=f'<header><h1>{esc(s["title"])}</h1>{sub}</header>'
    if kind=='question': content=f'<div class="repeats" aria-label="Три однакові символи">{led("×")*3}<span class="next-symbol">?</span></div><p class="question">{esc(s["question"])}</p>'
    elif kind=='model': content='<div class="model-row">'+''.join(f'<div><b class="step-number">0{i+1}</b><h2>{esc(a)}</h2><p>{esc(b)}</p></div>' for i,(a,b) in enumerate(s['items']))+'</div>'
    elif kind=='statement': content=f'<div class="statement-art" aria-hidden="true"><span>1…3</span><span>≠</span><span>майбутнє</span></div><p class="emphasis">{esc(s["emphasis"])}</p>'
    elif kind=='mapping': content='<div class="mapping-grid">'+''.join(f'<div><div class="map-number">{i} <span>→</span></div>{led(symbol)}<h2>{name}</h2></div>' for i,symbol,name in [(1,'?','Можливо'),(2,'×','Ні'),(3,'✓','Так')])+'</div>'
    elif kind=='sequence': content='<ol class="sequence-list">'+''.join(f'<li><b>{i+1:02d}</b><span>{esc(t)}</span></li>' for i,t in enumerate(s['items']))+'</ol>'
    elif kind=='flow': content=flow()
    elif kind=='pseudo': content=f'<pre class="pseudo"><code>{esc(s["code"])}</code></pre>'
    elif kind=='blocks': content='<div class="block-list">'+''.join(f'<div><span>{esc(a)}</span><strong>{esc(b)}</strong></div>' for a,b in s['items'])+'</div><p class="small">Назви блоків і категорії · схема збирання</p>'
    elif kind=='code': content=f'<pre class="source{(" compact" if s.get("compact") else "")}"><code>{highlight(s["code"])}</code></pre>'
    elif kind=='tests': content='<div class="test-row">'+''.join(f'<div><b>{esc(a)}</b><span>→</span><strong>{esc(b)}</strong><p>{esc(c)}</p></div>' for a,b,c in s['items'])+f'</div><p class="emphasis">{esc(s["emphasis"])}</p>'
    elif kind=='extensions': content='<div class="extensions-grid"><div><h2>Кнопки A і B</h2><p class="button-symbols">A → ✓<br>B → ×</p><p>Струшування лишається випадковим.</p></div><div><h2>Лише micro:bit V2</h2><p class="sound-line">Гучно → тихо → відповідь</p><p>Досліди гучність. Датчик не розпізнає слова.</p></div></div>'
    elif kind=='ai': content=f'<blockquote>{esc(s["quote"])}</blockquote><ul class="checks">'+''.join(f'<li>{esc(x)}</li>' for x in s['items'])+'</ul>'
    elif kind=='closing': content=''
    else: raise ValueError('Unknown layout '+kind)
    return heading+'<div class="content">'+content+'</div>'

