JS=r'''
const data=JSON.parse(document.getElementById('presentationData').textContent);
const slides=[...document.querySelectorAll('article.slide')];let index=0;
const prev=document.getElementById('prevSlide'),next=document.getElementById('nextSlide'),count=document.getElementById('slideCount'),notes=document.getElementById('teacherNotes'),toggle=document.getElementById('notesToggle');
const picker=document.getElementById('slidePicker');data.slides.forEach((slide,i)=>{const option=document.createElement('option');option.value=i;option.textContent=`${i+1}. ${slide.title}`;picker.append(option);});picker.addEventListener('change',()=>show(Number(picker.value)));
function show(n){index=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>s.hidden=i!==index);prev.disabled=index===0;next.disabled=index===slides.length-1;count.textContent=`${index+1} / ${slides.length}`;picker.value=String(index);document.getElementById('slidePickerNumber').textContent=String(index+1);document.getElementById('notesText').textContent=data.slides[index].notes;document.title=`${index+1} · ${data.slides[index].title} · ${data.title}`;window.scrollTo(0,0);if(document.activeElement===prev&&prev.disabled)next.focus();if(document.activeElement===next&&next.disabled)prev.focus();}
function closeDeck(){if(window.parent!==window){window.parent.postMessage({type:'lesson-presentation-close'},'*');}else{window.location.href=data.lesson_file;}}
prev.onclick=()=>show(index-1);next.onclick=()=>show(index+1);document.getElementById('closeDeck').onclick=closeDeck;document.getElementById('printDeck').onclick=()=>window.print();
toggle.onclick=()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));notes.hidden=!open;};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closeDeck();return;}if(e.altKey||e.ctrlKey||e.metaKey||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;const actions={ArrowRight:()=>show(index+1),ArrowDown:()=>show(index+1),ArrowLeft:()=>show(index-1),ArrowUp:()=>show(index-1),Home:()=>show(0),End:()=>show(slides.length-1)};if(actions[e.key]){e.preventDefault();actions[e.key]();}});show(0);
'''

def render(source):
    data=json.loads(source.read_text(encoding='utf-8-sig'))
    assert 14 <= len(data['slides']) <= 16
    articles='\n'.join(f'<article class="slide {esc(s["layout"])}" aria-label="{i+1}. {esc(s["title"])}"{(" hidden" if i else "")}>{body(s)}<span class="slide-number" aria-hidden="true">{i+1:02d}</span></article>' for i,s in enumerate(data['slides']))
    embedded=json.dumps(data,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    output=f'''<!doctype html><html lang="uk"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(data['title'])}</title><style>{CSS}</style></head><body><div class="toolbar"><span class="deck-label">Магічна куля · презентація</span><span class="spacer"></span><div class="slide-picker-top"><span id="slidePickerNumber" aria-hidden="true">1</span><select id="slidePicker" aria-label="Перейти до слайда"></select></div><button id="notesToggle" aria-expanded="false" aria-controls="teacherNotes">Нотатки вчителя</button><button id="printDeck">Друк</button><button id="closeDeck" aria-label="Закрити презентацію й повернутися до уроку">Закрити ×</button></div><main aria-label="Слайди презентації">{articles}</main><nav class="navigation" aria-label="Навігація слайдами"><button id="prevSlide">← Назад</button><span id="slideCount" role="status" aria-live="polite"></span><button id="nextSlide">Далі →</button></nav><p class="key-hint">Клавіші ← → · Home / End · Esc — повернутися до уроку</p><aside id="teacherNotes" hidden aria-label="Нотатки вчителя"><h2>Нотатки вчителя</h2><p id="notesText"></p></aside><script id="presentationData" type="application/json">{embedded}</script><script>{JS}</script></body></html>'''
    destination=source.with_name('presentation.html')
    destination.write_text(output,encoding='utf-8')
    print(f'Rendered {len(data["slides"])} slides: {destination}')

if __name__=='__main__':
    render(Path(sys.argv[1]).resolve() if len(sys.argv)>1 else ROOT/'presentation.json')
